[{"order":1,"type":"heading","text":"Monitoring, Error Tracking, and Observability in Next.js Production"},{"order":2,"type":"paragraph","text":"Achieving high availability and reliability in a production Next.js application requires a robust observability strategy. By combining Sentry for error tracking and OpenTelemetry for distributed tracing, you can gain deep insights into both client-side and server-side execution."},{"order":3,"type":"subheading","text":"1. Setting up Sentry for Next.js"},{"order":4,"type":"paragraph","text":"Sentry captures unhandled exceptions across your Server Components, Client Components, and API routes. To quickly configure Sentry in your Next.js project, run the automated setup wizard provided by their CLI."},{"order":5,"type":"code","text":"npx @sentry/wizard@latest -s nextjs"},{"order":6,"type":"paragraph","text":"This command automatically generates the necessary configuration files including sentry.client.config.ts, sentry.server.config.ts, and updates your next.config.mjs to handle source maps upload during build time."},{"order":7,"type":"subheading","text":"2. Configuring OpenTelemetry for Distributed Tracing"},{"order":8,"type":"paragraph","text":"Next.js has built-in support for OpenTelemetry. You can instrument your application to send traces to collectors like Jaeger, Honeycomb, or Datadog. First, install the required OpenTelemetry packages."},{"order":9,"type":"code","text":"npm install @opentelemetry/sdk-node @opentelemetry/api"},{"order":10,"type":"paragraph","text":"Create an instrumentation.ts file in the root directory of your project (or inside the src directory if you use one) to initialize the OpenTelemetry Node SDK."},{"order":11,"type":"code","text":"import { RegisterOptions } from 'next';
import { NodeSDK } from '@opentelemetry/sdk-node';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-http';
import { Resource } from '@opentelemetry/resources';
import { SemanticResourceAttributes } from '@opentelemetry/semantic-conventions';

export function register() {
  if (process.env.NEXT_RUNTIME === 'nodejs') {
    const sdk = new NodeSDK({
      resource: new Resource({
        [SemanticResourceAttributes.SERVICE_NAME]: 'my-nextjs-app',
      }),
      traceExporter: new OTLPTraceExporter({
        url: 'https://your-otel-collector-endpoint/v1/traces',
      }),
    });
    sdk.start();
  }
}"},{"order":12,"type":"subheading","text":"3. Enabling Instrumentation in Next Config"},{"order":13,"type":"paragraph","text":"You must explicitly enable the instrumentation hook inside your next.config.mjs file to let Next.js know it should load your telemetry setup."},{"order":14,"type":"code","text":"const nextConfig = {
  experimental: {
    instrumentationHook: true,
  },
};

export default nextConfig;"},{"order":15,"type":"subheading","text":"Best Practices for Production Observability"},{"order":16,"type":"bullet_point","text":"Sanitize PII: Ensure user passwords, tokens, and personally identifiable information are scrubbed before sending payloads to Sentry or OpenTelemetry."},{"order":17,"type":"bullet_point","text":"Source Maps: Always upload source maps during your CI/CD build pipeline to properly de-obfuscate client-side stack traces."},{"order":18,"type":"bullet_point","text":"Sampling Rates: Adjust trace and error sampling rates in high-traffic production environments to manage ingestion costs effectively."}]
